<?php
/**
 * PixelMani: replaces web/.htaccess WITHOUT a moment of public access.
 *
 * GENERATED by `npm run package:websupport` into install/ of the package,
 * with the expected SHA-256 of the package's web/.htaccess and a one-time
 * token. Upload it into web/ (under a name that contains the token) only for
 * the swap; it deletes itself after a successful install.
 *
 * Why: uploading or renaming .htaccess by hand (WebFTP) either truncates the
 * active file or removes it for a while, and during that time the password
 * protection is gone. This tool never removes the active file: it copies it
 * to a backup and then renames the verified new file OVER it with one
 * rename() in the same directory. On Linux that is rename(2), which replaces
 * the target atomically: every request sees either the old or the new file,
 * complete, and both carry the same password gate.
 *
 * It refuses unless:
 *   - the request itself came through HTTP Basic Auth (REMOTE_USER): the
 *     current gate is demonstrably active while this runs
 *   - the active .htaccess and .htaccess.new both carry the Basic Auth gate
 *     with the SAME password file (AuthUserFile)
 *   - .htaccess.new is byte for byte the package's web/.htaccess (SHA-256)
 *   - the server is POSIX (rename(2)) and both files are on one filesystem
 *
 * Actions (all text/plain, no paths, no secrets):
 *   ?action=check                       report only; changes nothing (default)
 *   ?action=preflight&confirm=TOKEN     creates pm-preflight-TOKEN/ holding the
 *                                       NEW .htaccess and probe.txt, to prove
 *                                       Apache accepts it here (401, then 200)
 *   ?action=install&confirm=TOKEN&preflight=passed
 *                                       backup + atomic swap + self-delete
 */

declare(strict_types=1);

const EXPECTED_SHA256 = '{{EXPECTED_SHA256}}';
const TOKEN = '{{TOKEN}}';
// Only true in a --local-test package (Windows test Apache). Never on the host.
const ALLOW_NON_POSIX = '{{ALLOW_NON_POSIX}}' === 'true';

header('Content-Type: text/plain; charset=utf-8');
header('Cache-Control: no-store');
header('X-Robots-Tag: noindex');
ini_set('display_errors', '0');

$dir = __DIR__;
$active = $dir . '/.htaccess';
$new = $dir . '/.htaccess.new';
$preflightDir = $dir . '/pm-preflight-' . TOKEN;
$report = [];
$problems = [];

function note(string $line): void
{
    global $report;
    $report[] = $line;
}
function problem(string $line): void
{
    global $problems;
    $problems[] = $line;
    note("STOP  $line");
}
function finish(int $status = 200): never
{
    global $report, $problems;
    http_response_code($status);
    echo "PixelMani .htaccess swap\n\n" . implode("\n", $report) . "\n\n"
        . ($problems ? 'RESULT: STOPPED. Nothing was changed. Do NOT replace .htaccess by hand.' : 'RESULT: OK') . "\n";
    exit;
}

/**
 * The Basic Auth gate in an .htaccess: exactly one each of "Require
 * valid-user", "AuthType Basic", AuthName and AuthUserFile, and no other
 * Require/Satisfy/Allow line that could open access. Returns the
 * AuthUserFile line or null.
 */
function gateOf(string $text, bool $isPixelmani): ?string
{
    $lines = array_values(array_filter(array_map('trim', preg_split('/\r?\n/', $text)), static fn ($l) => $l !== '' && $l[0] !== '#'));
    $count = static fn (string $re) => count(array_filter($lines, static fn ($l) => preg_match($re, $l) === 1));
    if ($count('/^Require\s+valid-user$/i') !== 1 || $count('/^AuthType\s+Basic$/i') !== 1
        || $count('/^AuthName\s+"[^"]+"$/i') !== 1 || $count('/^AuthUserFile\s+\S.*$/i') !== 1) {
        return null;
    }
    foreach ($lines as $line) {
        if (preg_match('/^(Require|Satisfy|Allow|Order|AuthMerging)\b/i', $line)
            && !preg_match('/^Require\s+(valid-user|all\s+denied)$/i', $line)) {
            return null;
        }
    }
    if (!$isPixelmani && count($lines) !== 4) {
        return null; // Websupport's own file: the four lines and nothing else
    }
    foreach ($lines as $line) {
        if (preg_match('/^AuthUserFile\s+/i', $line)) {
            return $line;
        }
    }
    return null;
}

$action = (string) ($_GET['action'] ?? 'check');
if (!in_array($action, ['check', 'preflight', 'install'], true)) {
    problem('unknown action');
    finish(400);
}

// ---- 1. this request came through the password gate
$user = (string) ($_SERVER['REMOTE_USER'] ?? $_SERVER['REDIRECT_REMOTE_USER'] ?? $_SERVER['PHP_AUTH_USER'] ?? '');
if ($user === '') {
    problem('this request did not come through HTTP Basic Auth (no REMOTE_USER): the current gate is not proven active');
} else {
    note('ok    this request is authenticated by the current password gate');
}

// ---- 2. the active file carries the gate
$activeText = is_file($active) ? (string) file_get_contents($active) : null;
$activeGate = $activeText === null ? null : (gateOf($activeText, false) ?? gateOf($activeText, true));
if ($activeGate === null) {
    problem('the active web/.htaccess is missing or is not a plain Basic Auth gate');
} else {
    note('ok    the active web/.htaccess carries the Basic Auth gate');
}

// ---- 3. the new file is exactly the package's, with the same gate
if (!is_file($new)) {
    problem('web/.htaccess.new is missing (upload the package\'s web/.htaccess under that name first)');
} else {
    $newText = (string) file_get_contents($new);
    if (!hash_equals(EXPECTED_SHA256, hash('sha256', $newText))) {
        problem('web/.htaccess.new is not byte for byte the package\'s web/.htaccess (SHA-256 differs: incomplete or wrong upload)');
    } else {
        note('ok    web/.htaccess.new matches the package (SHA-256)');
    }
    if (!str_starts_with($newText, "Require valid-user\n")) {
        problem('web/.htaccess.new does not start with "Require valid-user"');
    }
    $newGate = gateOf($newText, true);
    if ($newGate === null || $activeGate === null || !hash_equals($activeGate, $newGate)) {
        problem('web/.htaccess.new does not carry the SAME password gate (AuthUserFile) as the active file');
    } else {
        note('ok    both files use the same password file');
    }
}

// ---- 4. atomic replacement is available
$posix = PHP_OS_FAMILY !== 'Windows';
if (!$posix && !ALLOW_NON_POSIX) {
    problem('not a POSIX server: rename() is not guaranteed to replace atomically here');
} else {
    note($posix ? 'ok    POSIX rename(2): replaces the target atomically' : 'note  LOCAL TEST on Windows (not the host): MoveFileEx replace');
}
if (is_file($new) && is_file($active) && stat($new)['dev'] !== stat($active)['dev']) {
    problem('.htaccess and .htaccess.new are not on the same filesystem');
}
if (!is_writable($dir)) {
    problem('PHP cannot write to web/');
}

if ($action === 'check') {
    note($problems ? '' : 'ready: run ?action=preflight&confirm=<token> next');
    finish($problems ? 409 : 200);
}

// ---- actions that change something
if (!hash_equals(TOKEN, (string) ($_GET['confirm'] ?? ''))) {
    problem('missing or wrong confirm token');
    finish(403);
}
if ($problems) {
    finish(409);
}

if ($action === 'preflight') {
    if (!is_dir($preflightDir) && !@mkdir($preflightDir, 0755)) {
        problem('could not create the preflight folder');
        finish(500);
    }
    // The preflight folder gets its OWN gate (the new file) before its probe exists.
    $ok = @copy($new, $preflightDir . '/.htaccess') && @file_put_contents($preflightDir . '/probe.txt', "pixelmani-preflight-ok\n") !== false;
    if (!$ok) {
        problem('could not write the preflight files');
        finish(500);
    }
    note('ok    preflight folder created with the NEW .htaccess');
    note('next: open /pm-preflight-' . TOKEN . '/probe.txt in a PRIVATE window:');
    note('      without the password it must ask for one (401); with it, it must show "pixelmani-preflight-ok".');
    note('      A 500 means Apache refuses a directive here: STOP and report it.');
    note('      Then: ?action=install&confirm=<token>&preflight=passed');
    finish();
}

// install
if (($_GET['preflight'] ?? '') !== 'passed' || !is_dir($preflightDir)) {
    problem('run the preflight first and confirm it with preflight=passed');
    finish(409);
}
// Backup: a COPY; the active file stays in place until the atomic rename.
$backup = $dir . '/.htaccess.websupport-backup';
if (is_file($backup) && hash_file('sha256', $backup) !== hash('sha256', (string) $activeText)) {
    $backup = $dir . '/.htaccess.backup-' . gmdate('Ymd-His');
}
if (!@copy($active, $backup) || hash_file('sha256', $backup) !== hash('sha256', (string) $activeText)) {
    problem('could not write a verified backup of the active .htaccess; nothing replaced');
    finish(500);
}
note('ok    backup written: ' . basename($backup));

// One rename() over the active file. A failed attempt changes nothing (the
// old file stays complete), so a short retry is safe; it matters on Windows,
// where a file the web server is reading cannot be replaced at that instant.
$renamed = false;
$attempts = ALLOW_NON_POSIX ? 400 : 40;
for ($attempt = 0; $attempt < $attempts && !$renamed; $attempt++) {
    $renamed = @rename($new, $active);
    if (!$renamed) {
        usleep(ALLOW_NON_POSIX ? 10000 : 50000);
    }
}
if (!$renamed) {
    problem('rename failed; the active .htaccess is unchanged (safe to run install again)');
    finish(500);
}
clearstatcache();
if (!hash_equals(EXPECTED_SHA256, (string) hash_file('sha256', $active))) {
    problem('after the swap the active .htaccess is not the expected file: check immediately');
    finish(500);
}
note('ok    web/.htaccess replaced atomically; it is now the package\'s file (with the same gate)');

// The preflight folder goes only now: if the swap had failed, a retry still finds it.
foreach (['/.htaccess', '/probe.txt'] as $file) {
    @unlink($preflightDir . $file);
}
@rmdir($preflightDir);
note(is_dir($preflightDir) ? 'WARN  delete the folder pm-preflight-' . TOKEN . '/ by hand' : 'ok    preflight folder removed');

$deleted = @unlink(__FILE__);
note($deleted ? 'ok    this tool deleted itself' : 'WARN  could not delete this tool: delete it by hand (the new rules already refuse to run it)');
finish();
